schema_ddl:
CREATE TABLE clienti (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    cognome TEXT NOT NULL,
    email TEXT NOT NULL UNIQUE,
    citta TEXT,
    data_registrazione DATE NOT NULL DEFAULT CURRENT_DATE
);

CREATE TABLE ordini (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY,
    cliente_id INT NOT NULL REFERENCES clienti(id) ON DELETE CASCADE,
    data_ordine DATE NOT NULL,
    stato_ordine TEXT NOT NULL DEFAULT 'in_attesa' CHECK (stato_ordine IN ('in_attesa', 'pagato', 'spedito', 'consegnato', 'annullato')),
    importo_totale NUMERIC(10,2) NOT NULL CHECK (importo_totale >= 0),
    PRIMARY KEY (id, data_ordine)
) PARTITION BY RANGE (data_ordine);

CREATE TABLE ordini_2024_primo_semestre PARTITION OF ordini FOR VALUES FROM ('2024-01-01') TO ('2024-07-01');

CREATE TABLE ordini_2024_secondo_semestre PARTITION OF ordini FOR VALUES FROM ('2024-07-01') TO ('2025-01-01');

CREATE TABLE ordini_storico PARTITION OF ordini DEFAULT;
